#tongsci1-3-3-2-1-membrane3d .mb-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: linear-gradient(180deg, #d5ebf6 0%, #eef6f8 42%, #f7f4ec 50%, #eef6f8 58%, #d5ebf6 100%); }
