#tongsci1-3-3-2-1-membrane3d .mb-tools .btn { font-size: 19px !important; padding: 8px 14px !important; }
#tongsci1-3-3-2-1-membrane3d .mb-tag { pointer-events: auto; cursor: pointer; font-size: 18px; padding: 2px 10px; transition: opacity .25s, background .25s; }
#tongsci1-3-3-2-1-membrane3d .mb-tag:focus-visible { outline: 4px solid var(--hl); }
