#tongsci1-3-3-2-1-membrane3d .mb-tag.dim { opacity: .4; }
#tongsci1-3-3-2-1-membrane3d .mb-side { font-size: 17px; padding: 2px 10px; color: #1f5f8a; border-color: #5d9cc4; background: rgba(232, 245, 252, .9); }
#tongsci1-3-3-2-1-membrane3d .mb-bi { color: #8a4a12; border-color: #c98a3a; background: rgba(255, 246, 228, .9); }
#tongsci1-3-3-2-1-membrane3d .mb-mol { font-size: 15px; padding: 0 7px; border-width: 1.5px; background: rgba(255, 255, 255, .92); }
#tongsci1-3-3-2-1-membrane3d .mb-tray .tray-item { padding: 8px 13px; font-size: 18px; }
