#tongsci1-3-3-2-1-membrane3d .mb-tray .tray-item.pulse { animation: tongsci1-3-3-2-1-membrane3d--mb-pulse 1.5s ease-in-out infinite; }
@keyframes tongsci1-3-3-2-1-membrane3d--mb-pulse { 50% { box-shadow: 0 4px 0 var(--ink), 0 0 0 6px color-mix(in srgb, var(--hl) 80%, transparent); } }
#tongsci1-3-3-2-1-membrane3d .mb-panel { gap: 10px; }
#tongsci1-3-3-2-1-membrane3d .mb-out { margin: 0; font-size: 20px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 7px 14px; min-height: 2.9em; flex: none; }
#tongsci1-3-3-2-1-membrane3d .mb-card { border: 2px solid var(--ink); border-radius: 12px; background: var(--paper-2); padding: 10px 16px 12px; display: grid; align-content: start; gap: 6px; flex: 1 1 auto; min-height: 0; overflow: auto; }
#tongsci1-3-3-2-1-membrane3d .mb-card h3 { margin: 0; font: 800 28px/1.2 var(--f-display); color: var(--ink); border-left: 10px solid var(--c); padding-left: 12px; }
