#tongsci1-3-3-2-1-membrane3d .mb-card p { margin: 0; font-size: 19px; line-height: 1.5; }
#tongsci1-3-3-2-1-membrane3d .mb-card .mb-empty { color: var(--ink-3); }
#tongsci1-3-3-2-1-membrane3d .mb-card dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 3px 12px; font-size: 19px; line-height: 1.4; }
#tongsci1-3-3-2-1-membrane3d .mb-card dt { font-weight: 800; color: var(--ink-2); }
#tongsci1-3-3-2-1-membrane3d .mb-card dd { margin: 0; }
#tongsci1-3-3-2-1-membrane3d .mb-card .mb-tip { font-size: 17px; color: var(--ink-2); border-top: 1.5px dashed var(--rule); padding-top: 5px; }
#tongsci1-3-3-2-1-membrane3d .mb-lip { width: 100%; height: 200px; display: block; flex: none; font-family: var(--f-body); }
#tongsci1-3-3-2-1-membrane3d.u-done .mb-out { display: none; }
#tongsci1-3-3-2-1-membrane3d .mb-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 17px/1.25 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-2-1-membrane3d .mb-tab th { font: 800 17px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 4px; }
#tongsci1-3-3-2-1-membrane3d .mb-tab tbody th { background: color-mix(in srgb, var(--ink) 4%, var(--paper-2)); font-weight: 700; }
#tongsci1-3-3-2-1-membrane3d .mb-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 4px; text-align: center; color: var(--ink-3); }
#tongsci1-3-3-2-1-membrane3d .mb-tab td.ok { color: var(--good); background: var(--good-soft); font-weight: 800; }
#tongsci1-3-3-2-1-membrane3d .mb-tab td.no { color: #b23a22; background: #fde2dd; font-weight: 800; }
@media (prefers-reduced-motion: reduce) {
  #tongsci1-3-3-2-1-membrane3d .mb-tray .tray-item.pulse { animation: none; outline: 3px solid var(--hl); }
}

